class Solution {
public:
    vector<int> minDistinctFreqPair(vector<int>& nums) {
        map<int, int> freq;
        for (int x : nums) ++freq[x];
        for (auto it = freq.begin(); it != freq.end(); ++it) {
            auto jt = it; ++jt;
            for (; jt != freq.end(); ++jt)
                if (it->second != jt->second) return {it->first, jt->first};
        }
        return {-1, -1};
    }
};
